INSERT INTO public.lessons (position, title_fr, title_en, intro_fr, intro_en, takeaway_fr, takeaway_en) VALUES
(1,'Le message de la Bible','The Message of the Bible','La Bible n''est pas un livre ordinaire : elle raconte l''histoire d''un Dieu qui parle. Prenons le temps d''écouter ce qu''elle dit d''elle-même.','The Bible is no ordinary book: it tells the story of a God who speaks. Let''s take time to hear what it says about itself.','La Bible se présente comme la parole de Dieu, donnée pour éclairer et transformer la vie.','The Bible presents itself as God''s word, given to enlighten and transform life.'),
(2,'Le monde et son destin','The World and Its Destiny','Où va notre monde ? La Bible répond par une prophétie donnée à un roi de Babylone, il y a plus de 2 500 ans.','Where is our world heading? The Bible answers through a prophecy given to a king of Babylon more than 2,500 years ago.','L''histoire humaine n''est pas un hasard : elle avance vers le royaume éternel de Dieu.','Human history is not random: it moves toward God''s eternal kingdom.'),
(3,'Vers un monde nouveau','Toward a New World','Dieu ne se contente pas de réparer : il promet une création entièrement renouvelée.','God does not merely repair: he promises an entirely renewed creation.','La promesse finale de la Bible est un monde sans larmes, où Dieu habite avec les siens.','The Bible''s final promise is a world without tears, where God dwells with his people.'),
(4,'Le retour du Christ','The Return of Christ','L''espérance du retour de Jésus traverse toute l''Écriture. Découvrons ce que Jésus lui-même a promis.','The hope of Jesus'' return runs through all of Scripture. Let''s discover what Jesus himself promised.','Le retour de Jésus n''est pas un événement secret, mais une manifestation glorieuse et visible par tous.','Jesus'' return is not a secret event, but a glorious manifestation visible to all.'),
(5,'Les signes des temps','The Signs of the Times','Jésus a donné des repères pour que ses disciples ne soient pas surpris : non des sujets de peur, mais d''attente confiante.','Jesus gave signposts so his disciples would not be caught unaware: not reasons for fear, but for confident expectation.','Les signes invitent à la vigilance sereine, non à l''angoisse ni aux calculs de dates.','The signs invite calm watchfulness, not anxiety or date-setting.'),
(6,'Dieu existe','God Exists','Avant de parler de doctrines, arrêtons-nous sur une question simple : qui est ce Dieu que la Bible nous présente ?','Before speaking of doctrines, let''s pause on a simple question: who is this God the Bible presents?','Le Dieu de la Bible est créateur, personnel, et son caractère se résume en un mot : amour.','The God of the Bible is creator, personal, and his character is summed up in one word: love.'),
(7,'Satan','Satan','Le mal n''a pas toujours existé. La Bible en explique l''origine avec sobriété.','Evil has not always existed. The Bible explains its origin soberly.','Satan est un être vaincu par la croix ; son pouvoir est réel mais limité et temporaire.','Satan is a being defeated by the cross; his power is real but limited and temporary.'),
(8,'Jésus-Christ','Jesus Christ','Au centre de la Bible se tient une personne. Découvrons qui est Jésus et pourquoi il est venu.','At the centre of the Bible stands a person. Let''s discover who Jesus is and why he came.','Jésus est pleinement Dieu et pleinement homme : il connaît notre faiblesse et il peut sauver.','Jesus is fully God and fully human: he knows our weakness and he can save.'),
(9,'Le péché','Sin','Le mot « péché » peut sembler dur. La Bible l''emploie pourtant avec tendresse : elle nomme le mal pour pouvoir le guérir.','The word "sin" can sound harsh. Yet the Bible uses it tenderly: it names the illness in order to heal it.','Le péché est une rupture de relation ; le remède n''est pas l''effort, mais la grâce.','Sin is a broken relationship; the remedy is not effort, but grace.'),
(10,'La conversion','Conversion','La conversion n''est pas un effort de perfection : c''est un retournement du cœur vers celui qui nous aime.','Conversion is not an effort at perfection: it is a turning of the heart toward the one who loves us.','Se convertir, c''est accepter d''être aimé et de laisser Dieu conduire.','To be converted is to accept being loved and to let God lead.'),
(11,'La nouvelle naissance','The New Birth','Jésus parle d''un commencement radicalement nouveau, offert à chacun, quel que soit son passé.','Jesus speaks of a radically new beginning, offered to everyone, whatever their past.','La nouvelle naissance est l''œuvre de l''Esprit, pas un exploit humain.','The new birth is the Spirit''s work, not a human achievement.'),
(12,'La Loi de Dieu','The Law of God','La loi de Dieu n''est pas un fardeau : c''est le portrait de son caractère et une protection pour la vie.','God''s law is not a burden: it is the portrait of his character and a protection for life.','La loi révèle l''amour ; la grâce donne la force de le vivre.','The law reveals love; grace gives the strength to live it.'),
(13,'Le septième jour','The Seventh Day','Au cœur de la semaine, Dieu a placé un jour de repos. Voyons son origine et son sens.','At the heart of the week God placed a day of rest. Let''s look at its origin and meaning.','Le sabbat est un cadeau : un temps béni pour respirer avec Dieu.','The Sabbath is a gift: a blessed time to breathe with God.'),
(14,'Le dimanche','Sunday','Comment le premier jour de la semaine a-t-il pris tant d''importance ? Regardons ce que dit l''Écriture, sans polémique.','How did the first day of the week become so important? Let''s look at what Scripture says, without polemics.','L''Écriture reste notre repère quand la coutume et le commandement divergent.','Scripture remains our reference when custom and commandment diverge.'),
(15,'La prière','Prayer','Prier, c''est simplement parler avec un Père qui écoute. Aucun vocabulaire particulier n''est requis.','To pray is simply to speak with a Father who listens. No special vocabulary is required.','La prière est une relation, pas une performance.','Prayer is a relationship, not a performance.'),
(16,'La mort','Death','Ce sujet touche chacun de nous. La Bible en parle avec réalisme et avec une espérance étonnante.','This subject touches each of us. The Bible speaks of it realistically and with a surprising hope.','La mort est un sommeil dont Jésus vient réveiller les siens.','Death is a sleep from which Jesus comes to wake his own.'),
(17,'L''enfer','Hell','Beaucoup d''images populaires ne viennent pas de la Bible. Lisons les textes eux-mêmes.','Many popular images do not come from the Bible. Let''s read the texts themselves.','Dieu est juste et il ne se réjouit pas de la souffrance : le mal aura une fin.','God is just and takes no delight in suffering: evil will have an end.'),
(18,'Le millénium','The Millennium','Mille ans mentionnés dans l''Apocalypse : que se passe-t-il durant cette période, et où ?','A thousand years mentioned in Revelation: what happens during that period, and where?','Le millénium est un temps de jugement transparent, où toutes les questions reçoivent réponse.','The millennium is a time of transparent judgment, when every question receives an answer.'),
(19,'Le jugement','The Judgment','Le jugement de Dieu n''est pas une menace pour celui qui a confiance : c''est la garantie que la justice existe.','God''s judgment is not a threat for the one who trusts: it is the guarantee that justice exists.','Le juge est aussi l''avocat : Jésus se tient de notre côté.','The judge is also the advocate: Jesus stands on our side.'),
(20,'La véritable Église','The True Church','Comment reconnaître une communauté fidèle à Jésus ? L''Apocalypse donne des repères simples.','How can we recognise a community faithful to Jesus? Revelation gives simple markers.','L''Église n''est pas parfaite, mais elle est reconnaissable à sa fidélité à Jésus et à sa Parole.','The church is not perfect, but it is recognisable by its faithfulness to Jesus and his Word.'),
(21,'Le baptême','Baptism','Le baptême est une réponse d''amour, jamais une contrainte. Voyons son sens dans le Nouveau Testament.','Baptism is a response of love, never a constraint. Let''s see its meaning in the New Testament.','Le baptême exprime publiquement une décision intérieure déjà prise avec Jésus.','Baptism publicly expresses an inner decision already made with Jesus.'),
(22,'La libéralité','Stewardship and Generosity','Tout ce que nous avons est reçu. La générosité est la joie de rendre une part à celui qui donne tout.','Everything we have is received. Generosity is the joy of returning a share to the one who gives everything.','Donner n''appauvrit pas : cela libère le cœur.','Giving does not impoverish: it frees the heart.'),
(23,'La santé','Health','Le corps n''est pas séparé de la vie spirituelle. Dieu s''intéresse à notre bien-être entier.','The body is not separate from spiritual life. God cares about our whole well-being.','Prendre soin de son corps fait partie de la reconnaissance envers le Créateur.','Caring for the body is part of gratitude toward the Creator.'),
(24,'Sur les traces de Jésus','Following in Jesus'' Footsteps','Suivre Jésus, c''est marcher avec lui au quotidien : dans le service, le pardon et la confiance.','Following Jesus means walking with him daily: in service, forgiveness and trust.','La vie chrétienne est un chemin partagé, pas une performance solitaire.','The Christian life is a shared path, not a solitary performance.'),
(25,'Résumé des leçons 23 et 24','Summary of Lessons 23 and 24','Une relecture paisible de ce que nous avons découvert sur la santé et sur la marche avec Jésus.','A peaceful review of what we discovered about health and about walking with Jesus.','Revenir sur le chemin parcouru aide à avancer avec assurance.','Looking back over the road travelled helps us move forward with assurance.');

INSERT INTO public.lesson_questions (lesson_id, position, verse_ref, prompt_fr, prompt_en)
