FROM (VALUES
(1,1,'2 Timothée 3:16-17','Quelle est l''origine de l''Écriture, et à quoi est-elle utile ?','What is the origin of Scripture, and what is it useful for?'),
(1,2,'2 Pierre 1:20-21','Comment les prophètes ont-ils reçu leur message ?','How did the prophets receive their message?'),
(1,3,'Psaume 119:105','À quoi la parole de Dieu est-elle comparée ?','What is God''s word compared to?'),
(1,4,'Jean 17:17','Que dit Jésus au sujet de la parole du Père ?','What does Jesus say about the Father''s word?'),
(2,1,'Daniel 2:31-35','Décrivez la statue vue par Nebucadnetsar.','Describe the statue Nebuchadnezzar saw.'),
(2,2,'Daniel 2:37-40','Quels royaumes sont représentés par les différents métaux ?','Which kingdoms are represented by the different metals?'),
(2,3,'Daniel 2:44','Quel royaume viendra après tous les autres ?','Which kingdom will come after all the others?'),
(2,4,'Daniel 2:45','Pourquoi cette prophétie est-elle digne de confiance ?','Why can this prophecy be trusted?'),
(3,1,'Ésaïe 65:17','Que Dieu annonce-t-il qu''il va créer ?','What does God announce he will create?'),
(3,2,'Apocalypse 21:1-4','Qu''est-ce qui disparaîtra dans le monde nouveau ?','What will disappear in the new world?'),
(3,3,'Ésaïe 35:5-6','Quels changements sont promis pour les corps humains ?','What changes are promised for human bodies?'),
(3,4,'2 Pierre 3:13','Quelle attitude le croyant adopte-t-il face à cette promesse ?','What attitude does the believer take toward this promise?'),
(4,1,'Jean 14:1-3','Quelle promesse Jésus a-t-il faite à ses disciples avant son départ ?','What promise did Jesus make to his disciples before he left?'),
(4,2,'Actes 1:9-11','Comment le Christ reviendra-t-il, selon les anges ?','How will Christ return, according to the angels?'),
(4,3,'Matthieu 24:27','Ce retour sera-t-il discret ou visible ?','Will this return be quiet or visible?'),
(4,4,'1 Thessaloniciens 4:16-17','Que se passera-t-il pour les croyants à ce moment-là ?','What will happen to believers at that moment?'),
