(22,2,'2 Corinthiens 9:7','Dans quel esprit faut-il donner ?','In what spirit should we give?'),
(22,3,'Actes 20:35','Quelle parole de Jésus Paul rappelle-t-il ?','Which saying of Jesus does Paul recall?'),
(22,4,'1 Chroniques 29:14','Quelle est la source de ce que nous offrons ?','What is the source of what we offer?'),
(23,1,'1 Corinthiens 6:19-20','Comment Paul décrit-il le corps du croyant ?','How does Paul describe the believer''s body?'),
(23,2,'1 Corinthiens 10:31','Quel principe guide nos choix quotidiens ?','What principle guides our daily choices?'),
(23,3,'Genèse 1:29','Quel régime alimentaire est présenté au commencement ?','What diet is presented at the beginning?'),
(23,4,'3 Jean 2','Quel souhait Jean exprime-t-il pour son ami ?','What wish does John express for his friend?'),
(24,1,'1 Pierre 2:21','À quoi sommes-nous appelés ?','What are we called to?'),
(24,2,'Jean 13:14-15','Quel exemple Jésus laisse-t-il à ses disciples ?','What example does Jesus leave his disciples?'),
(24,3,'Matthieu 11:28-30','Quelle invitation Jésus adresse-t-il aux fatigués ?','What invitation does Jesus give the weary?'),
(24,4,'Philippiens 1:6','Qui achève l''œuvre commencée en nous ?','Who completes the work begun in us?'),
(25,1,'1 Corinthiens 10:31','Quel principe résume les choix de santé ?','What principle summarises health choices?'),
(25,2,'1 Pierre 2:21','Que signifie suivre les traces de Jésus aujourd''hui ?','What does following Jesus'' footsteps mean today?'),
(25,3,'Josué 24:15','Quelle décision personnelle ce verset propose-t-il ?','What personal decision does this verse propose?'),
(25,4,'Philippiens 4:13','Où trouvons-nous la force de continuer ?','Where do we find the strength to continue?')
) AS v(lpos, qpos, ref, fr, en)
JOIN public.lessons l ON l.position = v.lpos;